/* ================================================================ 20260915090000_audio_only.sql */

do $cn_migration$
begin
  /* Already applied, or already done by something that did not write the ledger. */
  if not exists (select 1 from public.applied_migrations where name = '20260915090000_audio_only.sql')
     and (to_regclass('public.app_schema') is not null) then
    insert into public.applied_migrations (name) values ('20260915090000_audio_only.sql')
